            'name' => '加星期測試',
            'CampusID' => 1,
            'ClassID' => 1,
            'enable' => 1,
            'MDT' => now(),
            'Notify_Token' => '',
        ]);

        $course = StudentClass::create([
            'StudentID' => $student->id,
            'GradeID' => 1,
            'SubjectID' => 1,
            'TeacherID' => 99,
            'by1' => 1,
            'Period' => 4,
            'StartDate' => '2026-03-16',
            'TotalHours' => 20,
            'Charge' => 0,
            'Paid' => 0,
            'Rate' => 1500,
            'RoomID' => '1',
            'MDate' => now(),
            'Stop' => 0,
            'ScheduleMode' => 'count',
            'SessionCount' => 11,
            'SessionDuration' => 120,
            'RemainingSessions' => 5,
            'UsedSessions' => 6,
            'ClassType' => 'one_on_two',
            'week' => 1,
            'time' => '16:30:00',
            'week1' => 2,
            'time1' => '16:30:00',
        ]);

        $pastSession = ClassSession::create([
            'StudentClassID' => $course->ID,
            'SessionDate' => '2026-03-16',
            'StartTime' => '16:30:00',
            'EndTime' => '18:30:00',
            'Status' => 'attended',
        ]);
        StudentSignIn::create([
            'StudentClassID' => $course->ID,
            'StudentID' => $student->id,
            'TeacherID' => 99,
            'GradeID' => 1,
            'SubjectID' => 1,
            'CampusID' => 1,
            'SignInDT' => '2026-03-16 16:30:00',
            'MDT' => now(),
            'ClassSessionID' => $pastSession->id,
            'Status' => 'present',
            'SessionDeducted' => 1,
        ]);

        foreach ([
            ['2026-04-13', 1], // Mon
            ['2026-04-14', 2], // Tue
            ['2026-04-20', 1], // Mon
            ['2026-04-21', 2], // Tue
            ['2026-04-27', 1], // Mon
        ] as [$date, $dow]) {
            ClassSession::create([
                'StudentClassID' => $course->ID,
                'SessionDate' => $date,
                'StartTime' => '16:30:00',
                'EndTime' => '18:30:00',
                'Status' => 'scheduled',
            ]);
        }

        $res = $this->withHeaders([
            'Authorization' => "Bearer {$token}",
            'Accept' => 'application/json',
        ])->putJson("/api/v1/student-classes/{$course->ID}", [
            'subject' => 'Math',
            'class_type' => 'one_on_two',
            'duration_hours' => 2,
            'days_of_week' => [1, 2, 4],
            'start_time' => '16:30',
            'day_time_slots' => [
                ['day' => 1, 'start_time' => '16:30'],
                ['day' => 2, 'start_time' => '16:30'],
                ['day' => 4, 'start_time' => '16:30'],
            ],
            'payment_type' => 'session',
        ]);

        $res->assertOk();
        $sync = $res->json('session_sync');
        $this->assertGreaterThan(0, (int) ($sync['updated_future_sessions'] ?? 0),
            'Sessions must be remapped when a new weekday is added to the contract');

